ALTER TABLE public.leads ADD COLUMN first_contact_at timestamptz;
CREATE FUNCTION public.record_first_lead_contact() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF OLD.first_contact_at IS NULL AND NEW.last_contact_at IS NOT NULL THEN NEW.first_contact_at := NEW.last_contact_at; ELSE NEW.first_contact_at := OLD.first_contact_at; END IF; RETURN NEW; END $$;
CREATE TRIGGER preserve_first_contact BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.record_first_lead_contact();
CREATE OR REPLACE FUNCTION public.lead_metrics() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT jsonb_build_object('total',count(*),'new',count(*) FILTER(WHERE status='new'),'call_scheduled',count(*) FILTER(WHERE status='call_scheduled'),'proposal_sent',count(*) FILTER(WHERE status='proposal_sent'),'converted',count(*) FILTER(WHERE status='converted'),'average_first_contact_hours',avg(extract(epoch FROM (first_contact_at-created_at))/3600) FILTER(WHERE first_contact_at IS NOT NULL),'by_source',(SELECT coalesce(jsonb_object_agg(source,n),'{}'::jsonb) FROM (SELECT source,count(*) n FROM public.leads GROUP BY source) s),'by_service',(SELECT coalesce(jsonb_object_agg(service_interest,n),'{}'::jsonb) FROM (SELECT service_interest,count(*) n FROM public.leads GROUP BY service_interest) s)) FROM public.leads $$;